import { readFileSync } from 'fs';

/** One ADSP service in the capability catalog (`capabilities.json`, generated by `scripts/capabilities.mjs`). */
export interface CatalogService {
  id: string;
  name: string;
  /** The service index's "Use it to" line. */
  use: string;
  /** The service guide, as a path for `read_adsp_doc`. */
  doc: string;
  /** Whether project-planner-service has a specialist for the service. Without one, there is no purpose or fit questions. */
  specialist: boolean;
  purpose: string | null;
  fitQuestions: string[];
  dependsOn: string[];
  risks: string[];
  /** `ServiceRegistration` fields that the SDK writes to this service's configuration. */
  registrationFields: string[];
  /** The planner patterns that map this service, with each pattern's reason for it. */
  patterns: { pattern: string; reason: string }[];
}

/** A need no ADSP service covers, as a planner pattern records it. */
export interface KnownGap {
  requirement: string;
  reason: string;
  suggestedApproach: string;
  keywords: string[];
}

export interface CatalogPattern {
  id: string;
  name: string;
  domainLanguage: string[];
  signals: string[];
  commonFeatures: string[];
  services: string[];
  unsupported: KnownGap[];
}

export interface CapabilityCatalog {
  sources: string[];
  services: CatalogService[];
  patterns: CatalogPattern[];
}

export function loadCapabilityCatalog(path: string): CapabilityCatalog {
  return JSON.parse(readFileSync(path, 'utf8'));
}
